(* keep_hierarchy = "yes" *) (* keep = "true" *) module calc_alpha_pow (
                  iInput,
                  num1,
                  calcAlphaPow
                  /* verilator lint_off UNUSED */
                  ,
                  clk,
                  clr,
                  rstn
                  /* verilator lint_on UNUSED */
                  );
        parameter  PARAM_POLY_WIDTH = 6;
        parameter  PARAM_w = 6;
        input  [3*6-1:0] iInput;
        input  [PARAM_POLY_WIDTH-1   :0] num1;
        output [PARAM_POLY_WIDTH-1   :0] calcAlphaPow;
                  /* verilator lint_off UNUSED */
        input clk;
        input rstn;
        input clr;
                  /* verilator lint_on UNUSED */





// 1'b1 + 1'b1 + 1'b1 + carry from previous loc
// 3'b100, so 2 extra bits as 1 bit belongs to 6-1

wire [3*6-1:0] iInput_int;
wire [6+1:0] iInput_mm0_W;
wire [6-1:0] iInputW;

assign iInput_int = {iInput}; //width matching

assign iInput_mm0_W =
               {2'b0, iInput_int[1*6-1:0*6]} +
               {2'b0, iInput_int[2*6-1:1*6]} +
               {2'b0, iInput_int[3*6-1:2*6]} ;

assign iInputW = iInput_mm0_W[6-1:0] +
                 {{(6-2){1'b0}}, iInput_mm0_W[6+1:6]};









             wire [PARAM_w-1:0] mult_z1_00000;
             wire [PARAM_w-1:0] mult_z1_00001;
             wire [PARAM_w-1:0] mult_z1_00002;
             wire [PARAM_w-1:0] mult_z1_00003;
             wire [PARAM_w-1:0] mult_z1_00004;
             wire [PARAM_w-1:0] mult_z1_00005;


             reg [PARAM_w-1:0] mult_a_00000;
             reg [PARAM_w-1:0] mult_a_00001;
             reg [PARAM_w-1:0] mult_a_00002;
             reg [PARAM_w-1:0] mult_a_00003;
             reg [PARAM_w-1:0] mult_a_00004;
             reg [PARAM_w-1:0] mult_a_00005;
             reg [PARAM_w-1:0] mult_a_00006;


always @(*)
begin
     begin
             mult_a_00000 =  num1;
     end
end
always @(*)
begin
     begin
             mult_a_00001 =
                                (iInputW[1-1] == 1'd1)  ?  mult_z1_00000 :
                                                            mult_a_00000 ;
     end
end
always @(*)
begin
     begin
             mult_a_00002 =
                                (iInputW[2-1] == 1'd1)  ?  mult_z1_00001 :
                                                            mult_a_00001 ;
     end
end
always @(*)
begin
     begin
             mult_a_00003 =
                                (iInputW[3-1] == 1'd1)  ?  mult_z1_00002 :
                                                            mult_a_00002 ;
     end
end
always @(*)
begin
     begin
             mult_a_00004 =
                                (iInputW[4-1] == 1'd1)  ?  mult_z1_00003 :
                                                            mult_a_00003 ;
     end
end
always @(*)
begin
     begin
             mult_a_00005 =
                                (iInputW[5-1] == 1'd1)  ?  mult_z1_00004 :
                                                            mult_a_00004 ;
     end
end
always @(*)
begin
     begin
             mult_a_00006 =
                                (iInputW[6-1] == 1'd1)  ?  mult_z1_00005 :
                                                            mult_a_00005 ;
     end
end


 PowcrcMult PowcrcMult_00000(
                   .prdct_z(mult_z1_00000),
                   .fact_a(mult_a_00000),
                   .fact_b(6'd2)
                  );

 PowcrcMult PowcrcMult_00001(
                   .prdct_z(mult_z1_00001),
                   .fact_a(mult_a_00001),
                   .fact_b(6'd4)
                  );

 PowcrcMult PowcrcMult_00002(
                   .prdct_z(mult_z1_00002),
                   .fact_a(mult_a_00002),
                   .fact_b(6'd16)
                  );

 PowcrcMult PowcrcMult_00003(
                   .prdct_z(mult_z1_00003),
                   .fact_a(mult_a_00003),
                   .fact_b(6'd12)
                  );

 PowcrcMult PowcrcMult_00004(
                   .prdct_z(mult_z1_00004),
                   .fact_a(mult_a_00004),
                   .fact_b(6'd19)
                  );

 PowcrcMult PowcrcMult_00005(
                   .prdct_z(mult_z1_00005),
                   .fact_a(mult_a_00005),
                   .fact_b(6'd9)
                  );


assign calcAlphaPow = mult_a_00006;

endmodule


(* keep_hierarchy = "yes" *) (* keep = "true" *) module PowcrcMult(
                   prdct_z,
                   fact_a,
                   fact_b
                  );


  parameter  PARAM_POLY_WIDTH = 6;
  parameter  PARAM_PRIMITIVE_POLY = 3;

    output [PARAM_POLY_WIDTH-1:0] prdct_z;
    input [PARAM_POLY_WIDTH-1:0] fact_a;
    input [PARAM_POLY_WIDTH-1:0] fact_b;

    wire [PARAM_POLY_WIDTH-1:0] out_prdct_z;
    wire [PARAM_POLY_WIDTH-1:0] in_fact_a;
    wire [PARAM_POLY_WIDTH-1:0] in_fact_b;
    assign  in_fact_a = fact_a;
    assign  in_fact_b = fact_b;
    assign  prdct_z = out_prdct_z;
assign out_prdct_z[ 0] = 
 ((in_fact_b[ 0] & ( 0  ^ in_fact_a[ 0] ))) ^ 
 ((in_fact_b[ 1] & ( 0  ^ in_fact_a[ 5] ))) ^ 
 ((in_fact_b[ 2] & ( 0  ^ in_fact_a[ 4] ))) ^ 
 ((in_fact_b[ 3] & ( 0  ^ in_fact_a[ 3] ))) ^ 
 ((in_fact_b[ 4] & ( 0  ^ in_fact_a[ 2] ))) ^ 
 ((in_fact_b[ 5] & ( 0  ^ in_fact_a[ 1] ))) ^ 
0;
assign out_prdct_z[ 1] = 
 ((in_fact_b[ 0] & ( 0  ^ in_fact_a[ 1] ))) ^ 
 ((in_fact_b[ 1] & ( 0  ^ in_fact_a[ 0]  ^ in_fact_a[ 5] ))) ^ 
 ((in_fact_b[ 2] & ( 0  ^ in_fact_a[ 4]  ^ in_fact_a[ 5] ))) ^ 
 ((in_fact_b[ 3] & ( 0  ^ in_fact_a[ 3]  ^ in_fact_a[ 4] ))) ^ 
 ((in_fact_b[ 4] & ( 0  ^ in_fact_a[ 2]  ^ in_fact_a[ 3] ))) ^ 
 ((in_fact_b[ 5] & ( 0  ^ in_fact_a[ 1]  ^ in_fact_a[ 2] ))) ^ 
0;
assign out_prdct_z[ 2] = 
 ((in_fact_b[ 0] & ( 0  ^ in_fact_a[ 2] ))) ^ 
 ((in_fact_b[ 1] & ( 0  ^ in_fact_a[ 1] ))) ^ 
 ((in_fact_b[ 2] & ( 0  ^ in_fact_a[ 0]  ^ in_fact_a[ 5] ))) ^ 
 ((in_fact_b[ 3] & ( 0  ^ in_fact_a[ 4]  ^ in_fact_a[ 5] ))) ^ 
 ((in_fact_b[ 4] & ( 0  ^ in_fact_a[ 3]  ^ in_fact_a[ 4] ))) ^ 
 ((in_fact_b[ 5] & ( 0  ^ in_fact_a[ 2]  ^ in_fact_a[ 3] ))) ^ 
0;
assign out_prdct_z[ 3] = 
 ((in_fact_b[ 0] & ( 0  ^ in_fact_a[ 3] ))) ^ 
 ((in_fact_b[ 1] & ( 0  ^ in_fact_a[ 2] ))) ^ 
 ((in_fact_b[ 2] & ( 0  ^ in_fact_a[ 1] ))) ^ 
 ((in_fact_b[ 3] & ( 0  ^ in_fact_a[ 0]  ^ in_fact_a[ 5] ))) ^ 
 ((in_fact_b[ 4] & ( 0  ^ in_fact_a[ 4]  ^ in_fact_a[ 5] ))) ^ 
 ((in_fact_b[ 5] & ( 0  ^ in_fact_a[ 3]  ^ in_fact_a[ 4] ))) ^ 
0;
assign out_prdct_z[ 4] = 
 ((in_fact_b[ 0] & ( 0  ^ in_fact_a[ 4] ))) ^ 
 ((in_fact_b[ 1] & ( 0  ^ in_fact_a[ 3] ))) ^ 
 ((in_fact_b[ 2] & ( 0  ^ in_fact_a[ 2] ))) ^ 
 ((in_fact_b[ 3] & ( 0  ^ in_fact_a[ 1] ))) ^ 
 ((in_fact_b[ 4] & ( 0  ^ in_fact_a[ 0]  ^ in_fact_a[ 5] ))) ^ 
 ((in_fact_b[ 5] & ( 0  ^ in_fact_a[ 4]  ^ in_fact_a[ 5] ))) ^ 
0;
assign out_prdct_z[ 5] = 
 ((in_fact_b[ 0] & ( 0  ^ in_fact_a[ 5] ))) ^ 
 ((in_fact_b[ 1] & ( 0  ^ in_fact_a[ 4] ))) ^ 
 ((in_fact_b[ 2] & ( 0  ^ in_fact_a[ 3] ))) ^ 
 ((in_fact_b[ 3] & ( 0  ^ in_fact_a[ 2] ))) ^ 
 ((in_fact_b[ 4] & ( 0  ^ in_fact_a[ 1] ))) ^ 
 ((in_fact_b[ 5] & ( 0  ^ in_fact_a[ 0]  ^ in_fact_a[ 5] ))) ^ 
0;
endmodule
