(* keep_hierarchy = "yes" *) (* keep = "true" *) module Frnyscaler_3_16(fact_a,cntl,sum_y);

input[15:0] fact_a;
input[2:0] cntl;
output[18:0] sum_y;

wire[17:0] a0;
wire[17:0] a1;
wire[17:0] a2;
wire[2:0]  fact_b = cntl;

wire [17:0] sum0;
wire [17:0] carry0;
/* verilator lint_off UNUSED */
wire [18:0] carry0_1;
/* verilator lint_on UNUSED */

assign a0 = fact_b[0] ? {2'b0,fact_a} : 18'b0;
assign a1 = fact_b[1] ? {1'b0,fact_a,1'b0} : 18'b0;
assign a2 = fact_b[2] ? {fact_a,2'b0} : 18'b0;



assign sum0 = a0 ^ a1 ^ a2;
assign carry0 = {a0 & a1} | {a1 & a2} | {a2 & a0};


assign carry0_1 = {carry0,1'b0};

assign sum_y = sum0 + carry0_1;
//assign sum_y = fact_a *cntl;


endmodule




(* keep_hierarchy = "yes" *) (* keep = "true" *) module Frnyscaler_4_16(fact_a,cntl,sum_y);

input[15:0] fact_a;
