wire[18:0] a2;
wire[18:0] a3;
wire[3:0]  fact_b = cntl;

wire [18:0] sum0;
wire [18:0] carry0;
/* verilator lint_off UNUSED */
wire [19:0] carry0_1;
/* verilator lint_on UNUSED */

wire [18:0] sum1;
wire [18:0] carry1;
wire [19:0] carry1_1;


assign a0 = fact_b[0] ? {3'b0,fact_a} : 19'b0;
assign a1 = fact_b[1] ? {2'b0,fact_a,1'b0} : 19'b0;
assign a2 = fact_b[2] ? {1'b0,fact_a,2'b0} : 19'b0;
assign a3 = fact_b[3] ? {fact_a,3'b0} : 19'b0;



assign sum0 = a0 ^ a1 ^ a2;
assign carry0 = {a0 & a1} | {a1 & a2} | {a2 & a0};


assign carry0_1 = {carry0,1'b0};



assign sum1 = sum0 ^ carry0_1[18:0] ^ a3;
assign carry1 = {sum0 & carry0_1[18:0]} | {carry0_1[18:0] & a3} | {a3 & sum0};


assign carry1_1 = {carry1,1'b0};




assign sum_y = sum1 + carry1_1;

